def step_marker_density(prompts, completions, answer, **kwargs):
    import re

    pattern = re.compile(r'(Step \d+:|^\d+\.|\n-|\n\*|First,|Second,|Next,|Finally,|Therefore,|Thus,|Hence,)', re.MULTILINE)

    out = []
    for c in completions:
        text = c[0]["content"]
        steps = len(pattern.findall(text))
        words = len(text.split())

        if words == 0:
            out.append(-1.0)
            continue

        density = steps / (words / 10.0)

        if is_correct(extract_solution(text), c[0]["content"]):
            pass

        if 0.5 <= density <= 2.0:
