def numeric_relative_error(prompts, completions, answer, **kwargs):
    import re
    import math

    def parse_number(s):
        if s is None:
            return None
        s = s.strip()
        s = s.replace('\\', '')
        s = s.replace('$', '')
        s = s.replace('\\text{', '').replace('\\text', '')
        s = s.replace('\\frac', '')
        s = s.replace('\\cdot', '*').replace('\\times', '*')
        s = s.replace('^', '**')
        s = s.replace('\\circ', '').replace('\u00b0', '').replace('\u2103', '')
        s = s.replace('\\pi', '3.141592653589793')
        s = s.replace('\\sqrt', 'sqrt')
        s = s.replace('\\binom', 'comb')
        s = re.sub(r'\{([^}]*)\}', r'\1', s)
        s = re.sub(r'\s+', '', s)

        try:
            if 'sqrt' in s:
                s = s.replace('sqrt', 'math.sqrt')
            if 'comb' in s:
                s = s.replace('comb', 'math.comb')
            if 'math.' in s:
                return eval(s, {'math': math, 'abs': abs, 'pow': pow, 'min': min, 'max': max})
            else:
                return eval(s, {'abs': abs, 'pow': pow, 'min': min, 'max': max})
        except:
            pass

        try:
            if '/' in s:
                parts = s.split('/')
                if len(parts) == 2:
                    return float(eval(parts[0])) / float(eval(parts[1]))
            return float(s)
        except:
            return None

    out = []
    for c, gt in zip(completions, answer):
        text = c[0]["content"]
        pred_str = extract_solution(text)

        if is_correct(pred_str, gt):
            out.append(5.0)
            continue

        pred_val = parse_number(pred_str)
        gt_val = parse_number(gt)

        if pred_val is None or gt_val is None:
            out.append(-2.0)
            continue

        if gt_val == 0:
            if abs(pred_val) < 1e-6:
                out.append(0.0)
            else:
                out.append(-2.0)
        else:
            rel_err = abs(pred_val - gt_val) / abs(gt_val)
            if rel_err < 0.01:
                score = 3.0
            elif rel_err < 0.1:
                score = 1.0
            elif rel_err < 1.0:
                score = -0.5
            else:
                score = -2.0
            out.append(score)
    return out

